-- ---------------------------------------------------------------- После
SELECT 'ПОСЛЕ' AS этап,
       (SELECT COUNT(*) FROM browser_site)          AS сайтов,
       (SELECT COUNT(*) FROM browser_scenario)      AS сценариев,
       (SELECT COUNT(*) FROM browser_workflow)      AS цепочек,
       (SELECT COUNT(*) FROM browser_workflow_step) AS звеньев;

-- Настройка присутствия на месте? Без неё панель анкет не работает.
SELECT id, name, url, LENGTH(COALESCE(presence, '')) AS presence_bytes
  FROM browser_site ORDER BY id;

-- Сценарии сайта 19 с числом шагов — сверить с локальными.
SELECT id, name, status, JSON_LENGTH(steps) AS шагов
  FROM browser_scenario WHERE site_id = 19 ORDER BY id;

-- Целостность звеньев: каждое смотрит на существующий сценарий.
SELECT s.workflow_id, s.position, s.scenario_id,
       IF(c.id IS NULL, 'СЦЕНАРИЯ НЕТ', c.name) AS сценарий
  FROM browser_workflow_step s
  LEFT JOIN browser_scenario c ON c.id = s.scenario_id
 ORDER BY s.workflow_id, s.position;
